    { const char * tb_v958 = "// как в POSIX: файл на месте назначения заменяется (обычный rename на Windows так не умеет)\n"; *(const char * *)tb_grow(v_lines) = tb_v958; }
    { const char * tb_v959 = "static int tb_win_rename(const char *from, const char *to) {\n"; *(const char * *)tb_grow(v_lines) = tb_v959; }
    { const char * tb_v960 = "    wchar_t *a = tb_wide(from), *b = tb_wide(to);\n"; *(const char * *)tb_grow(v_lines) = tb_v960; }
    { const char * tb_v961 = "    int ok = a && b && MoveFileExW(a, b, MOVEFILE_REPLACE_EXISTING);\n"; *(const char * *)tb_grow(v_lines) = tb_v961; }
