    { const char * tb_v1055 = "// подсказки для clang / gcc: ошибка бывает редко, а tb_crash не возвращается\n"; *(const char * *)tb_grow(v_lines) = tb_v1055; }
    { const char * tb_v1056 = "#if defined(__GNUC__)\n"; *(const char * *)tb_grow(v_lines) = tb_v1056; }
