    { const char * tb_v1175 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v1175; }
    { const char * tb_v1176 = "#define TB_WIN_STACK_MSG \"стек переполнен: функция зовёт себя слишком глубоко (рекурсия без конца?)\\n\"\n"; *(const char * *)tb_grow(v_lines) = tb_v1176; }
    { const char * tb_v1177 = "// переполнение стека — сразу (это никогда не «нормальное» исключение)\n"; *(const char * *)tb_grow(v_lines) = tb_v1177; }
    { const char * tb_v1178 = "static LONG CALLBACK tb_win_overflow(EXCEPTION_POINTERS *e) {\n"; *(const char * *)tb_grow(v_lines) = tb_v1178; }
    { const char * tb_v1179 = "    if (e->ExceptionRecord->ExceptionCode == EXCEPTION_STACK_OVERFLOW) tb_win_fatal(TB_WIN_STACK_MSG);\n"; *(const char * *)tb_grow(v_lines) = tb_v1179; }
    { const char * tb_v1180 = "    return EXCEPTION_CONTINUE_SEARCH;\n"; *(const char * *)tb_grow(v_lines) = tb_v1180; }
    { const char * tb_v1181 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v1181; }
    { const char * tb_v1182 = "// остальные падения — только если их никто не поймал\n"; *(const char * *)tb_grow(v_lines) = tb_v1182; }
    { const char * tb_v1183 = "static LONG WINAPI tb_win_crashed(EXCEPTION_POINTERS *e) {\n"; *(const char * *)tb_grow(v_lines) = tb_v1183; }
