    { const char * tb_v1194 = "// начало программы на Windows: русский текст в консоли, цвета, слова запуска в UTF-8,\n"; *(const char * *)tb_grow(v_lines) = tb_v1194; }
    { const char * tb_v1195 = "// понятное сообщение при переполнении стека\n"; *(const char * *)tb_grow(v_lines) = tb_v1195; }
    { const char * tb_v1196 = "static void tb_win_init(int *argc, char ***argv) {\n"; *(const char * *)tb_grow(v_lines) = tb_v1196; }
    { const char * tb_v1197 = "    SetConsoleOutputCP(CP_UTF8);\n"; *(const char * *)tb_grow(v_lines) = tb_v1197; }
    { const char * tb_v1198 = "    SetConsoleCP(CP_UTF8);\n"; *(const char * *)tb_grow(v_lines) = tb_v1198; }
    { const char * tb_v1199 = "    // \\n остаётся \\n (как на Linux и Mac): одинаковый вывод в файл и в трубу\n"; *(const char * *)tb_grow(v_lines) = tb_v1199; }
    { const char * tb_v1200 = "    _setmode(_fileno(stdout), _O_BINARY);\n"; *(const char * *)tb_grow(v_lines) = tb_v1200; }
