    { const char * tb_v1205 = "    if (GetConsoleMode(err, &mode) && SetConsoleMode(err, mode | 0x0004)) tb_win_vt = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v1205; }
    { const char * tb_v1206 = "    int n = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v1206; }
