    { const char * tb_v1224 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v1224; }
    { const char * tb_v1225 = "// main() зовёт tb_guard_init(): на Windows ей нужны ещё argc и argv из main\n"; *(const char * *)tb_grow(v_lines) = tb_v1225; }
    { const char * tb_v1226 = "#define tb_guard_init() tb_win_init(&argc, &argv)\n"; *(const char * *)tb_grow(v_lines) = tb_v1226; }
    { const char * tb_v1227 = "#else\n"; *(const char * *)tb_grow(v_lines) = tb_v1227; }
    { const char * tb_v1228 = "static void tb_guard_init(void) {\n"; *(const char * *)tb_grow(v_lines) = tb_v1228; }
    { const char * tb_v1229 = "    static char alt[65536];\n"; *(const char * *)tb_grow(v_lines) = tb_v1229; }
