    { const char * tb_v2280 = "// ---------- http_get: страница из интернета через curl (есть на Mac и почти на любом Linux) ----------\n"; *(const char * *)tb_grow(v_lines) = tb_v2280; }
    { const char * tb_v2281 = "static const char *tb_http_get(const char *url) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2281; }
    { const char * tb_v2282 = "    if (strncmp(url, \"http://\", 7) != 0 && strncmp(url, \"https://\", 8) != 0) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2282; }
    { const char * tb_v2283 = "        tb_err = tb_cat(\"адрес должен начинаться с http:// или https://: \", url);\n"; *(const char * *)tb_grow(v_lines) = tb_v2283; }
    { const char * tb_v2284 = "        return \"\";\n"; *(const char * *)tb_grow(v_lines) = tb_v2284; }
    { const char * tb_v2285 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v2285; }
    { const char * tb_v2286 = "    // адрес — в одинарных кавычках для shell: ' внутри адреса пишется как '\\''\n"; *(const char * *)tb_grow(v_lines) = tb_v2286; }
    { const char * tb_v2287 = "    size_t n = strlen(url);\n"; *(const char * *)tb_grow(v_lines) = tb_v2287; }
    { const char * tb_v2288 = "    char *cmd = malloc(n * 4 + 80);\n"; *(const char * *)tb_grow(v_lines) = tb_v2288; }
