    { const char * tb_v2290 = "#ifdef _WIN32\n"; *(const char * *)tb_grow(v_lines) = tb_v2290; }
    { const char * tb_v2291 = "    // curl.exe есть в Windows 10 и новее; адрес — в двойных кавычках для cmd.exe,\n"; *(const char * *)tb_grow(v_lines) = tb_v2291; }
    { const char * tb_v2292 = "    // (внутри кавычек & | < > ^ для cmd — простые знаки), а \" внутри адреса — как %22\n"; *(const char * *)tb_grow(v_lines) = tb_v2292; }
    { const char * tb_v2293 = "    size_t k = (size_t)sprintf(cmd, \"curl.exe -fsSL --max-time 30 \\\"\");\n"; *(const char * *)tb_grow(v_lines) = tb_v2293; }
