    { const char * tb_v2304 = "        if (url[i] == '\\'') { memcpy(cmd + k, \"'\\\\''\", 4); k += 4; }\n"; *(const char * *)tb_grow(v_lines) = tb_v2304; }
    { const char * tb_v2305 = "        else cmd[k++] = url[i];\n"; *(const char * *)tb_grow(v_lines) = tb_v2305; }
