    { const char * tb_v2331 = "        return *p ? p + 1 : 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v2331; }
    { const char * tb_v2332 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v2332; }
    { const char * tb_v2333 = "    if (*p == '{' || *p == '[') {\n"; *(const char * *)tb_grow(v_lines) = tb_v2333; }
    { const char * tb_v2334 = "        int d = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v2334; }
    { const char * tb_v2335 = "        while (*p) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2335; }
    { const char * tb_v2336 = "            if (*p == '\"') { p = tb_js_skip(p); if (!p) return 0; continue; }\n"; *(const char * *)tb_grow(v_lines) = tb_v2336; }
    { const char * tb_v2337 = "            if (*p == '{' || *p == '[') d++;\n"; *(const char * *)tb_grow(v_lines) = tb_v2337; }
    { const char * tb_v2338 = "            else if (*p == '}' || *p == ']') { d--; if (d == 0) return p + 1; }\n"; *(const char * *)tb_grow(v_lines) = tb_v2338; }
    { const char * tb_v2339 = "            p++;\n"; *(const char * *)tb_grow(v_lines) = tb_v2339; }
