    { const char * tb_v2343 = "    const char *s = p;\n"; *(const char * *)tb_grow(v_lines) = tb_v2343; }
    { const char * tb_v2344 = "    while (*p && *p != ',' && *p != '}' && *p != ']' && *p != ' ' && *p != '\\n' && *p != '\\r' && *p != '\\t') p++;\n"; *(const char * *)tb_grow(v_lines) = tb_v2344; }
    { const char * tb_v2345 = "    return p == s ? 0 : p;\n"; *(const char * *)tb_grow(v_lines) = tb_v2345; }
    { const char * tb_v2346 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v2346; }
    { const char * tb_v2347 = "static int tb_js_hex(const char *p) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2347; }
    { const char * tb_v2348 = "    int v = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v2348; }
    { const char * tb_v2349 = "    for (int i = 0; i < 4; i++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2349; }
    { const char * tb_v2350 = "        char ch = p[i]; v <<= 4;\n"; *(const char * *)tb_grow(v_lines) = tb_v2350; }
    { const char * tb_v2351 = "        if (ch >= '0' && ch <= '9') v |= ch - '0';\n"; *(const char * *)tb_grow(v_lines) = tb_v2351; }
    { const char * tb_v2352 = "        else if (ch >= 'a' && ch <= 'f') v |= ch - 'a' + 10;\n"; *(const char * *)tb_grow(v_lines) = tb_v2352; }
