    { const char * tb_v2356 = "    return v;\n"; *(const char * *)tb_grow(v_lines) = tb_v2356; }
    { const char * tb_v2357 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v2357; }
    { const char * tb_v2358 = "// строка JSON (p смотрит на \") → обычный текст\n"; *(const char * *)tb_grow(v_lines) = tb_v2358; }
    { const char * tb_v2359 = "static const char *tb_js_str(const char *p) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2359; }
    { const char * tb_v2360 = "    const char *e = tb_js_skip(p);\n"; *(const char * *)tb_grow(v_lines) = tb_v2360; }
    { const char * tb_v2361 = "    if (!e) return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v2361; }
    { const char * tb_v2362 = "    char *out = tb_tmem(e - p + 1), *o = out;\n"; *(const char * *)tb_grow(v_lines) = tb_v2362; }
    { const char * tb_v2363 = "    p++;\n"; *(const char * *)tb_grow(v_lines) = tb_v2363; }
