    { const char * tb_v2528 = "} tb_dict;\n"; *(const char * *)tb_grow(v_lines) = tb_v2528; }
    { const char * tb_v2529 = "\n"; *(const char * *)tb_grow(v_lines) = tb_v2529; }
    { const char * tb_v2530 = "// ячейка таблицы: номер ключа + 1 (младшие 40 бит) и метка из старших битов хеша\n"; *(const char * *)tb_grow(v_lines) = tb_v2530; }
    { const char * tb_v2531 = "#define TB_DAT ((1LL << 40) - 1)\n"; *(const char * *)tb_grow(v_lines) = tb_v2531; }
    { const char * tb_v2532 = "#define TB_DTAG(h) ((long long)(((h) >> 40) << 40) & ~TB_DAT & 0x7FFFFFFFFFFFFFFFLL)\n"; *(const char * *)tb_grow(v_lines) = tb_v2532; }
    { const char * tb_v2533 = "static unsigned long long tb_hash(tb_dict *d, const void *k) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2533; }
    { const char * tb_v2534 = "    unsigned long long h = 1469598103934665603ULL;\n"; *(const char * *)tb_grow(v_lines) = tb_v2534; }
    { const char * tb_v2535 = "    if (d->text) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2535; }
    { const char * tb_v2536 = "        for (const unsigned char *p = *(const unsigned char * const *)k; *p; p++) { h ^= *p; h *= 1099511628211ULL; }\n"; *(const char * *)tb_grow(v_lines) = tb_v2536; }
    { const char * tb_v2537 = "    } else {\n"; *(const char * *)tb_grow(v_lines) = tb_v2537; }
    { const char * tb_v2538 = "        h ^= (unsigned long long)*(const long long *)k;\n"; *(const char * *)tb_grow(v_lines) = tb_v2538; }
    { const char * tb_v2539 = "        h *= 0x9E3779B97F4A7C15ULL;\n"; *(const char * *)tb_grow(v_lines) = tb_v2539; }
    { const char * tb_v2540 = "        h ^= h >> 32;\n"; *(const char * *)tb_grow(v_lines) = tb_v2540; }
    { const char * tb_v2541 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v2541; }
    { const char * tb_v2542 = "    return h;\n"; *(const char * *)tb_grow(v_lines) = tb_v2542; }
    { const char * tb_v2543 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v2543; }
    { const char * tb_v2544 = "static int tb_keq(tb_dict *d, const void *a, const void *b) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2544; }
    { const char * tb_v2545 = "    if (d->text) return strcmp(*(const char * const *)a, *(const char * const *)b) == 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v2545; }
    { const char * tb_v2546 = "    return *(const long long *)a == *(const long long *)b;\n"; *(const char * *)tb_grow(v_lines) = tb_v2546; }
    { const char * tb_v2547 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v2547; }
    { const char * tb_v2548 = "static inline long long tb_dfind(tb_dict *d, const void *k) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2548; }
    { const char * tb_v2549 = "    if (d->mode == 1) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2549; }
    { const char * tb_v2550 = "        unsigned long long at = (unsigned long long)(*(const long long *)k - d->base);\n"; *(const char * *)tb_grow(v_lines) = tb_v2550; }
    { const char * tb_v2551 = "        return at < (unsigned long long)d->keys->len ? (long long)at : -1;\n"; *(const char * *)tb_grow(v_lines) = tb_v2551; }
    { const char * tb_v2552 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v2552; }
    { const char * tb_v2553 = "    if (d->mode == 2) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2553; }
    { const char * tb_v2554 = "        unsigned long long o = (unsigned long long)(*(const long long *)k - d->base);\n"; *(const char * *)tb_grow(v_lines) = tb_v2554; }
    { const char * tb_v2555 = "        return o < (unsigned long long)d->npos ? d->pos[o] - 1 : -1;\n"; *(const char * *)tb_grow(v_lines) = tb_v2555; }
    { const char * tb_v2556 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v2556; }
    { const char * tb_v2557 = "    unsigned long long h = tb_hash(d, k), mask = d->nslots - 1, i = h & mask;\n"; *(const char * *)tb_grow(v_lines) = tb_v2557; }
    { const char * tb_v2558 = "    long long tag = TB_DTAG(h);\n"; *(const char * *)tb_grow(v_lines) = tb_v2558; }
    { const char * tb_v2559 = "    while (d->slots[i] != 0) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2559; }
    { const char * tb_v2560 = "        long long sl = d->slots[i];\n"; *(const char * *)tb_grow(v_lines) = tb_v2560; }
    { const char * tb_v2561 = "        // метка хеша совпала — только тогда сравниваем сами ключи (текст — дорого)\n"; *(const char * *)tb_grow(v_lines) = tb_v2561; }
