    { const char * tb_v2629 = "    if (l->data == 0) tb_crash(line, \"не хватило памяти\");\n"; *(const char * *)tb_grow(v_lines) = tb_v2629; }
    { const char * tb_v2630 = "    memset(l->data, 0, bytes);\n"; *(const char * *)tb_grow(v_lines) = tb_v2630; }
    { const char * tb_v2631 = "    l->len = 0; l->cap = cap;\n"; *(const char * *)tb_grow(v_lines) = tb_v2631; }
    { const char * tb_v2632 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v2632; }
    { const char * tb_v2633 = "static void tb_dclear(tb_dict *d, int line) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2633; }
    { const char * tb_v2634 = "    tb_lclear(d->keys, line);\n"; *(const char * *)tb_grow(v_lines) = tb_v2634; }
