    { const char * tb_v2637 = "    if (d->slots && !(tb_nchunks > 0 && tb_in_temp(d->slots))) tb_gc_free(d->slots);\n"; *(const char * *)tb_grow(v_lines) = tb_v2637; }
    { const char * tb_v2638 = "    d->slots = 0; d->pos = 0; d->npos = 0; d->base = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v2638; }
    { const char * tb_v2639 = "    if (d->text) tb_dreindex(d, 8);\n"; *(const char * *)tb_grow(v_lines) = tb_v2639; }
    { const char * tb_v2640 = "    else { d->mode = 1; d->nslots = 0; }\n"; *(const char * *)tb_grow(v_lines) = tb_v2640; }
    { const char * tb_v2641 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v2641; }
    { const char * tb_v2642 = "// новый ключ int k: можно ли остаться без поиска (mode 1 или 2)\n"; *(const char * *)tb_grow(v_lines) = tb_v2642; }
    { const char * tb_v2643 = "static void tb_dplace_int(tb_dict *d, long long k) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2643; }
    { const char * tb_v2644 = "    long long n = d->keys->len;          // уже вместе с новым ключом\n"; *(const char * *)tb_grow(v_lines) = tb_v2644; }
    { const char * tb_v2645 = "    if (d->mode == 1) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2645; }
    { const char * tb_v2646 = "        if (n == 1) { d->base = k; return; }\n"; *(const char * *)tb_grow(v_lines) = tb_v2646; }
