    { const char * tb_v2648 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v2648; }
    { const char * tb_v2649 = "    if (d->mode == 1 || d->mode == 2) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2649; }
    { const char * tb_v2650 = "        // плотно ли: ключи не дальше 4 ячеек на один ключ\n"; *(const char * *)tb_grow(v_lines) = tb_v2650; }
