    { const char * tb_v2755 = "#endif\n"; *(const char * *)tb_grow(v_lines) = tb_v2755; }
    { const char * tb_v2756 = "static int tb_dhas(tb_dict *d, const void *k) { return tb_dfind(d, k) >= 0; }\n"; *(const char * *)tb_grow(v_lines) = tb_v2756; }
    { const char * tb_v2757 = "static void tb_dremove(tb_dict *d, const void *k) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2757; }
    { const char * tb_v2758 = "    long long at = tb_dfind(d, k);\n"; *(const char * *)tb_grow(v_lines) = tb_v2758; }
    { const char * tb_v2759 = "    if (at < 0) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v2759; }
    { const char * tb_v2760 = "    if (d->mode != 0) tb_dto_hash(d);\n"; *(const char * *)tb_grow(v_lines) = tb_v2760; }
    { const char * tb_v2761 = "    long long last = d->keys->len - 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v2761; }
    { const char * tb_v2762 = "    // на место удалённого ставим последний: порядок меняется только у него\n"; *(const char * *)tb_grow(v_lines) = tb_v2762; }
    { const char * tb_v2763 = "    memcpy(d->keys->data + at * d->keys->size, d->keys->data + last * d->keys->size, d->keys->size);\n"; *(const char * *)tb_grow(v_lines) = tb_v2763; }
    { const char * tb_v2764 = "    memcpy(d->vals->data + at * d->vals->size, d->vals->data + last * d->vals->size, d->vals->size);\n"; *(const char * *)tb_grow(v_lines) = tb_v2764; }
    { const char * tb_v2765 = "    d->keys->len -= 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v2765; }
    { const char * tb_v2766 = "    d->vals->len -= 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v2766; }
    { const char * tb_v2767 = "    tb_dreindex(d, d->nslots);\n"; *(const char * *)tb_grow(v_lines) = tb_v2767; }
    { const char * tb_v2768 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v2768; }
    { const char * tb_v2769 = "static tb_dict *tb_dict_from(int text, long long vsize, long long n, const void *keys, const void *vals) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2769; }
    { const char * tb_v2770 = "    tb_dict *d = tb_dict_new(text, vsize);\n"; *(const char * *)tb_grow(v_lines) = tb_v2770; }
    { const char * tb_v2771 = "    long long ksize = d->keys->size;\n"; *(const char * *)tb_grow(v_lines) = tb_v2771; }
    { const char * tb_v2772 = "    for (long long i = 0; i < n; i++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2772; }
    { const char * tb_v2773 = "        memcpy(tb_dput(d, (const char *)keys + i * ksize, 0), (const char *)vals + i * vsize, vsize);\n"; *(const char * *)tb_grow(v_lines) = tb_v2773; }
    { const char * tb_v2774 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v2774; }
    { const char * tb_v2775 = "    return d;\n"; *(const char * *)tb_grow(v_lines) = tb_v2775; }
    { const char * tb_v2776 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v2776; }
    { const char * tb_v2777 = "\n"; *(const char * *)tb_grow(v_lines) = tb_v2777; }
    { const char * tb_v2778 = "// ---------- on all cores: цикл на всех ядрах ----------\n"; *(const char * *)tb_grow(v_lines) = tb_v2778; }
    { const char * tb_v2779 = "// Работа делится на куски; каждое ядро берёт следующий свободный кусок,\n"; *(const char * *)tb_grow(v_lines) = tb_v2779; }
    { const char * tb_v2780 = "// пока они не кончатся (так ядра не простаивают, если куски разные по тяжести).\n"; *(const char * *)tb_grow(v_lines) = tb_v2780; }
    { const char * tb_v2781 = "// shared: каждое ядро копит своё на «листке», потом один раз добавляет под замком.\n"; *(const char * *)tb_grow(v_lines) = tb_v2781; }
    { const char * tb_v2782 = "static pthread_mutex_t tb_par_lock = PTHREAD_MUTEX_INITIALIZER;\n"; *(const char * *)tb_grow(v_lines) = tb_v2782; }
    { const char * tb_v2783 = "static int tb_cores(void) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2783; }
    { const char * tb_v2784 = "    const char *want = getenv(\"TB_CORES\");   // TB_CORES=1 — проверить на одном ядре\n"; *(const char * *)tb_grow(v_lines) = tb_v2784; }
    { const char * tb_v2785 = "    long n = want != 0 ? atol(want) : sysconf(_SC_NPROCESSORS_ONLN);\n"; *(const char * *)tb_grow(v_lines) = tb_v2785; }
    { const char * tb_v2786 = "    return n < 1 ? 1 : (n > 256 ? 256 : (int)n);\n"; *(const char * *)tb_grow(v_lines) = tb_v2786; }
    { const char * tb_v2787 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v2787; }
    { const char * tb_v2788 = "#ifdef TB_BARE\n"; *(const char * *)tb_grow(v_lines) = tb_v2788; }
    { const char * tb_v2789 = "static void tb_par_run(void *(*work)(void *), void *job, long long total) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2789; }
    { const char * tb_v2790 = "    int n = tb_cores();\n"; *(const char * *)tb_grow(v_lines) = tb_v2790; }
    { const char * tb_v2791 = "    if (n > total) n = (int)total;\n"; *(const char * *)tb_grow(v_lines) = tb_v2791; }
    { const char * tb_v2792 = "    if (n < 1) n = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v2792; }
    { const char * tb_v2793 = "    pthread_t t[256];\n"; *(const char * *)tb_grow(v_lines) = tb_v2793; }
    { const char * tb_v2794 = "    for (int i = 1; i < n; i++)\n"; *(const char * *)tb_grow(v_lines) = tb_v2794; }
    { const char * tb_v2795 = "        if (pthread_create(&t[i], 0, work, job) != 0) tb_crash(0, \"не получилось запустить ядро\");\n"; *(const char * *)tb_grow(v_lines) = tb_v2795; }
    { const char * tb_v2796 = "    work(job);\n"; *(const char * *)tb_grow(v_lines) = tb_v2796; }
    { const char * tb_v2797 = "    for (int i = 1; i < n; i++) pthread_join(t[i], 0);\n"; *(const char * *)tb_grow(v_lines) = tb_v2797; }
    { const char * tb_v2798 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v2798; }
    { const char * tb_v2799 = "#else\n"; *(const char * *)tb_grow(v_lines) = tb_v2799; }
    { const char * tb_v2800 = "// Готовые потоки: создаются один раз (при первом on all cores) и ждут работу.\n"; *(const char * *)tb_grow(v_lines) = tb_v2800; }
    { const char * tb_v2801 = "// Раньше каждый цикл на ядрах создавал и закрывал потоки — для коротких циклов это было дольше самой работы.\n"; *(const char * *)tb_grow(v_lines) = tb_v2801; }
    { const char * tb_v2802 = "static pthread_mutex_t tb_pool_m = PTHREAD_MUTEX_INITIALIZER;\n"; *(const char * *)tb_grow(v_lines) = tb_v2802; }
    { const char * tb_v2803 = "static pthread_cond_t tb_pool_go = PTHREAD_COND_INITIALIZER, tb_pool_end = PTHREAD_COND_INITIALIZER;\n"; *(const char * *)tb_grow(v_lines) = tb_v2803; }
    { const char * tb_v2804 = "static int tb_pool_n = 0, tb_pool_want = 0, tb_pool_busy = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v2804; }
    { const char * tb_v2805 = "static volatile long long tb_pool_gen = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v2805; }
    { const char * tb_v2806 = "static volatile int tb_pool_left = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v2806; }
    { const char * tb_v2807 = "static void *(*tb_pool_work)(void *) = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v2807; }
    { const char * tb_v2808 = "static void *tb_pool_job = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v2808; }
    { const char * tb_v2809 = "static void *tb_pool_loop(void *arg) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2809; }
    { const char * tb_v2810 = "    int me = (int)(long long)arg;\n"; *(const char * *)tb_grow(v_lines) = tb_v2810; }
    { const char * tb_v2811 = "    // поток пула не считается «работающим», пока ждёт: уборка памяти может идти\n"; *(const char * *)tb_grow(v_lines) = tb_v2811; }
    { const char * tb_v2812 = "    __atomic_sub_fetch(&tb_gthreads, 1, __ATOMIC_RELEASE);\n"; *(const char * *)tb_grow(v_lines) = tb_v2812; }
    { const char * tb_v2813 = "    long long seen = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v2813; }
    { const char * tb_v2814 = "    for (;;) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2814; }
    { const char * tb_v2815 = "        // немного ждём без сна: циклы на ядрах часто идут один за другим\n"; *(const char * *)tb_grow(v_lines) = tb_v2815; }
    { const char * tb_v2816 = "        for (int spin = 0; spin < 20000 && __atomic_load_n(&tb_pool_gen, __ATOMIC_ACQUIRE) == seen; spin++)\n"; *(const char * *)tb_grow(v_lines) = tb_v2816; }
